<?php namespace Database\Seeders; use Illuminate\Database\Seeder; use Illuminate\Support\Facades\Hash; use App\Models\{School,Role,Permission,User,SchoolSetting}; class DatabaseSeeder extends Seeder {public function run(){ $s=School::firstOrCreate(['name'=>'King Castle School Muhammad Campus']);$roles=[];foreach([['Super Admin','super_admin'],['Admin','admin'],['Teacher','teacher']] as $x)$roles[$x[1]]=Role::firstOrCreate(['slug'=>$x[1]],['name'=>$x[0]]);foreach(['students.view','students.manage','teachers.view','teachers.manage','attendance.manage','fees.view','fees.manage','homework.manage','exams.manage','notices.manage','messages.manage','settings.manage','dashboard.view'] as $p)Permission::firstOrCreate(['slug'=>$p],['name'=>ucwords(str_replace('.',' ',$p))]);foreach($roles as $slug=>$role){$role->permissions()->sync(Permission::all()->pluck('id'));}foreach([['superadmin1@kcs.school','Super Admin','super_admin'],['admin@kcs.school','Admin','admin'],['teacher@kcs.school','Teacher','teacher']] as $x)User::firstOrCreate(['email'=>$x[0]],['school_id'=>$s->id,'role_id'=>$roles[$x[2]]->id,'name'=>$x[1],'password'=>Hash::make('password123')]);SchoolSetting::updateOrCreate(['school_id'=>$s->id],['school_name'=>'King Castle School Muhammad Campus','automatic_fee_reminders'=>false]);}}
